keyframes:
@keyframes bento-mobile-stack-slides { 
  0% { transform: translateY(var(--stack-offset)); opacity: 0; }
  10% { transform: translateY(calc(var(--stack-offset) - var(--offset-adjuster))); opacity: 1; }
  70% { transform: translateY(calc(var(--stack-offset) - var(--offset-adjuster))); opacity: 1; }
  100% { transform: translateY(calc(var(--stack-offset) - var(--offset-adjuster))); opacity: 0; }
}

@keyframes bento-mobile-stack-slides-front { 
  0% { transform: translateY(var(--stack-offset)); opacity: 0; }
  10% { transform: translateY(calc(var(--stack-offset) - var(--offset-adjuster))); opacity: 1; }
  100% { transform: translateY(calc(var(--stack-offset) - var(--offset-adjuster))); opacity: 1; }
}

@keyframes stack-section-exit { 
  0% { transform: translate(0px, 0px); }
  100% { transform: translate(0, calc(-1 * var(--section-exit-y))); }
}

@keyframes bento-items-shrink { 
  0%, 20% { transform: scale(1); box-shadow: var(--bento-shadow-none); }
  100% { transform: scale(var(--stack-scale, 1)); box-shadow: var(--bento-shadow); }
}

@keyframes bento-depth-mask-drive { 
  0%, 20% { --stack-depth-mask-t: 0; }
  100% { --stack-depth-mask-t: 1; }
}

@keyframes stack-title-stagger { 
  0% { opacity: 0; transform: translate(0, var(--parallax-translate-y)); }
  100% { opacity: 1; transform: translate(0px, 0px); }
}

@keyframes stack-title-card-match { 
  100% { translate: 0 calc(-1 * var(--title-catchup)); }
}

@keyframes clap-yaxis { 
  0% { animation-timing-function: cubic-bezier(0.65, 0.68, 0.4, 0.64); transform: translateY(0px) translate(0px) scale(0.5); opacity: 0; }
  50% { animation-timing-function: linear; transform: translateY(-120px) translate(20px) scale(1.3); opacity: 1; }
  100% { animation-timing-function: ease-out; transform: translateY(-180px) translate(40px) scale(0.1); opacity: 0; }
}

@keyframes clap-tocenter { 
  0% { animation-timing-function: cubic-bezier(0.65, 0.68, 0.4, 0.64); transform: translateY(-50px) translate(20px) scale(0.5); opacity: 0; }
  50% { animation-timing-function: linear; transform: translateY(-170px) translate(20px) scale(1.3); opacity: 1; }
  100% { animation-timing-function: ease-out; transform: translateY(-260px) translate(20px) scale(0.1); opacity: 0;

@keyframes out { 
  0% { animation-timing-function: ease-in-out; opacity: 1; }
  100% { animation-timing-function: ease-in-out; opacity: 0; }
}

@keyframes moveUp { 
  100% { animation-timing-function: ease-in-out; transform: translateY(-20px); opacity: 0.9; }
}

@keyframes moveInBottom { 
  0% { opacity: 1; transform: scale(1); }
  100% { opacity: 0; transform: scale(1.8); }
}

@keyframes show { 
  0% { animation-timing-function: ease-in-out; opacity: 0; }
  100% { animation-timing-function: ease-in-out; opacity: 1; }
}

@keyframes lds-ellipsis1 { 
  0% { transform: scale(0); }
  100% { transform: scale(1); }
}

@keyframes lds-ellipsis3 { 
  0% { transform: scale(1); }
  100% { transform: scale(0); }
}

@keyframes lds-ellipsis2 { 
  0% { transform: translate(0px); }
  100% { transform: translate(10px); }
}

@keyframes grow-featured-card-radius { 
  0% { clip-path: inset(0px); }
  100% { clip-path: inset(0 round var(--s2a-border-radius-md)); }
}

@keyframes logo-ticker-scroll { 
  0% { translate: calc(var(--logo-ticker-scroll-offset, 0px) * -1 * var(--logo-ticker-dir)); }
  100% { translate: calc((var(--logo-ticker-set-width, 0px) + var(--logo-ticker-scroll-offset, 0px)) * -1 * var(--logo-ticker-dir)); }
}

@keyframes sg-loading-spin { 
  100% { transform: rotate(360deg); }
}

@keyframes sg-loading-shimmer { 
  0% { background-position: 100% 0px; }
  100% { background-position: 0px 0px; }
}
